package cl.bolsillo.app;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Preferences belong to an Android widget id, preserving existing global defaults. */
final class WidgetPreferences {
 static String key(int id){return "widget-"+id;}
 static JSONObject read(Context c,int id){try{String saved=NativeStore.settings(c).getString(key(id),"");if(!saved.isEmpty())return new JSONObject(saved);String account=NativeStore.settings(c).getString("widgetAccount","");return new JSONObject().put("display",account.isEmpty()?"total":"account").put("account",account).put("palette",NativeStore.settings(c).getString("palette","prisma")).put("appearance",NativeStore.settings(c).getString("appearance","dark")).put("hidden",NativeStore.settings(c).getBoolean("widgetHidden",false)).put("layout","auto").put("actions",true);}catch(Exception ignored){return new JSONObject();}}
 static void write(Context c,int id,JSONObject options)throws Exception{if(!NativeStore.settings(c).edit().putString(key(id),options.toString()).commit())throw new Exception("No se pudo guardar el widget.");}
 static void remove(Context c,int id){NativeStore.settings(c).edit().remove(key(id)).apply();}
 static boolean belongs(Context c,int id){AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);return info!=null&&new ComponentName(c,BolsilloWidget.class).equals(info.provider);}
 static String summary(Context c,int id){JSONObject p=read(c,id);String name=p.optString("display","total");if(name.equals("account"))try{JSONObject cache=NativeStore.cached(c);JSONObject account=cache==null?null:Ledger.find(cache.getJSONObject("data").getJSONArray("accounts"),p.optString("account"));name=account==null?"Cuenta no disponible":account.optString("name");}catch(Exception ignored){name="Cuenta";}else name=name.equals("available")?"Disponible":name.equals("savings")?"Ahorros":"Patrimonio";return name+(p.optBoolean("hidden")?" · privado":"");}
 static void configure(Activity a,int id){a.startActivity(new Intent(a,WidgetConfigActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));}
 static void manage(Activity a){Dialog d=new GlassDialog(a);Glass.privacy(d.getWindow(),a);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=Glass.column(a);panel.addView(Glass.text(a,"Tus widgets",24,true));TextView hint=Glass.text(a,"Cada uno tiene su saldo, color y privacidad.",14,false);hint.setTextColor(Glass.subtle(a));panel.addView(hint);int[] ids=AppWidgetManager.getInstance(a).getAppWidgetIds(new ComponentName(a,BolsilloWidget.class));for(int id:ids){LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(Glass.dp(a,15),Glass.dp(a,14),Glass.dp(a,15),Glass.dp(a,14));row.setBackground(Glass.surface(a,210));row.addView(Glass.text(a,summary(a,id),16,true));TextView label=Glass.text(a,"Personalizar  ›",12,false);label.setTextColor(Glass.accent(a));row.addView(label);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=Glass.dp(a,10);panel.addView(row,p);row.setOnClickListener(v->{d.dismiss();configure(a,id);});}if(ids.length==0){TextView empty=Glass.text(a,"Tu dinero, también en la pantalla de inicio.",17,true);empty.setPadding(0,Glass.dp(a,24),0,Glass.dp(a,14));panel.addView(empty);}Button add=Glass.button(a,"Añadir widget");panel.addView(add);add.setOnClickListener(v->{AppWidgetManager manager=AppWidgetManager.getInstance(a);if(manager.isRequestPinAppWidgetSupported()){manager.requestPinAppWidget(new ComponentName(a,BolsilloWidget.class),null,null);d.dismiss();}else{hint.setText("Mantén pulsada la pantalla de inicio, abre Widgets y elige Bolsillo.");hint.announceForAccessibility(hint.getText());}});Button close=Glass.button(a,"Cerrar");panel.addView(close);close.setOnClickListener(v->d.dismiss());ScrollView scroll=new ScrollView(a);scroll.addView(panel);d.setContentView(scroll);d.show();}
 static final class Editor {
  final Activity a;final int id;final JSONObject options;final LinearLayout root,body;final ImageView background;final TextView previewTitle,previewLabel,previewAmount,previewMeta,message;final Runnable done;
  final List<String> modes=new ArrayList<>(),accountIds=new ArrayList<>(),names=new ArrayList<>();
  Editor(Activity activity,int widgetId,JSONObject draft,Runnable callback){a=activity;id=widgetId;options=draft==null?read(a,id):draft;done=callback;root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.setBackground(Glass.backdrop(a));root.setPadding(Glass.dp(a,20),Glass.dp(a,14),Glass.dp(a,20),Glass.dp(a,14));
   LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(Glass.text(a,"Tu widget",26,true),new LinearLayout.LayoutParams(0,-2,1));heading.addView(Modern.iconButton(a,"close","Cancelar configuración",a::finish),new LinearLayout.LayoutParams(Glass.dp(a,44),Glass.dp(a,44)));root.addView(heading);
   ScrollView scroll=new ScrollView(a);scroll.setVerticalScrollBarEnabled(false);body=new LinearLayout(a);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(0,Glass.dp(a,12),0,Glass.dp(a,16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
   FrameLayout preview=new FrameLayout(a);background=new ImageView(a);background.setScaleType(ImageView.ScaleType.FIT_XY);preview.addView(background,new FrameLayout.LayoutParams(-1,-1));LinearLayout content=new LinearLayout(a);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(Glass.dp(a,21),Glass.dp(a,18),Glass.dp(a,21),Glass.dp(a,18));previewTitle=Glass.text(a,"Bolsillo",16,true);content.addView(previewTitle);previewLabel=Glass.text(a,"Patrimonio",12,false);content.addView(previewLabel);previewAmount=Glass.text(a,"",32,true);Modern.fitAmount(previewAmount,16,32);content.addView(previewAmount);previewMeta=Glass.text(a,"",12,false);content.addView(previewMeta);preview.addView(content,new FrameLayout.LayoutParams(-1,-1));body.addView(preview,new LinearLayout.LayoutParams(-1,Glass.dp(a,164)));
   modes.add("total");accountIds.add("");names.add("Patrimonio total");modes.add("available");accountIds.add("");names.add("Dinero disponible");modes.add("savings");accountIds.add("");names.add("Ahorro e inversión");try{JSONArray accounts=NativeSettings.accounts(a);for(int i=0;i<accounts.length();i++){JSONObject account=accounts.getJSONObject(i);modes.add("account");accountIds.add(account.getString("id"));names.add(account.getString("name"));}}catch(Exception ignored){}
   section("Qué quieres ver");for(int i=0;i<names.size();i++){final int position=i;TextView pick=choice(names.get(i));body.addView(pick,margin(6));pick.setOnClickListener(v->{put("display",modes.get(position));put("account",accountIds.get(position));refreshChoices();});pick.setTag("display:"+i);}
   section("Paleta");choices("palette",new String[]{"prisma","ocean","amber"},new String[]{"Prisma","Océano","Ámbar"});section("Apariencia");choices("appearance",new String[]{"dark","light","system"},new String[]{"Oscuro","Claro","Sistema"});section("Distribución");choices("layout",new String[]{"auto","compact","full"},new String[]{"Adaptable","Compacta","Completa"});
   toggle("Ocultar importes","hidden",false);toggle("Acciones rápidas","actions",true);
   message=Glass.text(a,"",12,false);message.setTextColor(Glass.subtle(a));root.addView(message);Button save=Glass.button(a,"Guardar widget");root.addView(save);save.setOnClickListener(v->{try{if(!belongs(a,id))throw new Exception("Este widget ya no está en la pantalla de inicio.");write(a,id,options);BolsilloWidget.render(a,AppWidgetManager.getInstance(a),id);v.performHapticFeedback(HapticFeedbackConstants.CONFIRM);done.run();}catch(Exception e){message.setText(e.getMessage());message.announceForAccessibility(message.getText());}});refreshChoices();
  }
  void put(String key,Object value){try{options.put(key,value);}catch(JSONException ignored){}}
  LinearLayout.LayoutParams margin(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=Glass.dp(a,top);return p;}
  void section(String label){TextView title=Glass.text(a,label,14,true);title.setTextColor(Glass.subtle(a));body.addView(title,margin(20));}
  TextView choice(String label){TextView t=Glass.pill(a,label,false);t.setSingleLine(false);t.setMaxLines(2);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(Glass.dp(a,14),Glass.dp(a,11),Glass.dp(a,14),Glass.dp(a,11));t.setMinHeight(Glass.dp(a,48));return t;}
  void choices(String key,String[] values,String[] labels){LinearLayout row=new LinearLayout(a);for(int i=0;i<values.length;i++){final String value=values[i];TextView t=choice(labels[i]);t.setGravity(Gravity.CENTER);t.setTag(key+":"+value);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i>0)p.leftMargin=Glass.dp(a,4);row.addView(t,p);t.setOnClickListener(v->{put(key,value);refreshChoices();v.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);});}body.addView(row,margin(6));}
  void toggle(String label,String key,boolean fallback){Switch toggle=new Switch(a);Controls.style(toggle);toggle.setText(label);toggle.setMinHeight(Glass.dp(a,58));toggle.setChecked(options.optBoolean(key,fallback));body.addView(toggle,margin(9));toggle.setOnCheckedChangeListener((v,on)->{put(key,on);preview();});}
  void refreshChoices(){walk(body);preview();}
  void walk(ViewGroup group){for(int i=0;i<group.getChildCount();i++){View v=group.getChildAt(i);if(v instanceof ViewGroup)walk((ViewGroup)v);else if(v instanceof TextView&&v.getTag() instanceof String){String[] tag=((String)v.getTag()).split(":",2);boolean selected;if(tag[0].equals("display")){int n=Integer.parseInt(tag[1]);selected=options.optString("display","total").equals(modes.get(n))&&(!modes.get(n).equals("account")||options.optString("account").equals(accountIds.get(n)));}else selected=options.optString(tag[0],tag[0].equals("layout")?"auto":"system").equals(tag[1]);Glass.selectPill(a,(TextView)v,selected);}}}
  void preview(){WidgetSkin skin=new WidgetSkin(a,options);background.setImageBitmap(skin.surface(660,328,false));previewTitle.setTextColor(skin.ink);previewLabel.setTextColor(skin.subtle);previewAmount.setTextColor(skin.ink);previewMeta.setTextColor(skin.accent);try{BolsilloWidget.Snapshot snapshot=BolsilloWidget.snapshot(a,options);previewLabel.setText(snapshot.label);previewAmount.setText(snapshot.missing?"—":options.optBoolean("hidden")?"••••••":BolsilloWidget.money(snapshot.value));previewMeta.setText(options.optBoolean("hidden")?"Importes privados":"Saldo de tus registros locales");}catch(Exception e){previewLabel.setText("Tu saldo local");previewAmount.setText(options.optBoolean("hidden")?"••••••":"$0");previewMeta.setText("Abre Bolsillo para cargar tus cuentas");}}
 }
}
